import CryptoKit
import XCTest
@testable import FelicityDashboard

final class DoorbellAudioTests: XCTestCase {
    /// Digests were generated by compiling and executing the existing Android
    /// Java encoder/decoder against these exact inputs, independently of Swift.
    func testG722MatchesExistingAndroidCodecGoldenVectors() {
        let encodedDigests = [
            "f94385d17e0efbd8ad2df54d2290994ce07adc5935100df602c53aca16c84564",
            "41a0b551bb5ae6c1e1754d3edeabc1f364446587ccafc9eda81b467639a1efd1",
            "01f86d3c1741b47f265c99d0d315682f709a589de7319ce143e82c89506043fd"
        ]
        let decodedDigests = [
            "2d05e9b4bd625bafb1309d46365f36269a458c6b9372d9d36910dd150c117c85",
            "ca7d954c45b35a5ff9b8257fac64fdb5b81c7b77e0aff151ef7120252fa3a444",
            "7e62792c6f13d0bda9efe382f1d4ee83feae3585f45b57c6a61c8a37613b5f90"
        ]
        for scenario in 0..<3 {
            let pcm: [Int16] = (0..<3200).map { index in
                if scenario == 0 { return 0 }
                if scenario == 1 { return Int16((sin(Double(index) * 2 * .pi * 440 / 16_000) * 12_000).rounded()) }
                return Int16(truncatingIfNeeded: index * 7919 + 12345)
            }
            let encoded = DoorbellG722Encoder().encode(pcm)
            XCTAssertEqual(encoded.count, 1600)
            XCTAssertEqual(digest(encoded), encodedDigests[scenario])
            let decoded = DoorbellG722Decoder().decode(encoded)
            var bytes = Data()
            for sample in decoded { bytes.append(UInt8(truncatingIfNeeded: sample)); bytes.append(UInt8(truncatingIfNeeded: sample >> 8)) }
            XCTAssertEqual(decoded.count, 3200)
            XCTAssertEqual(digest(bytes), decodedDigests[scenario])
        }
    }

    func testCodecStateContinuesAcrossTwentyMillisecondPackets() {
        let pcm = (0..<1280).map { Int16(truncatingIfNeeded: $0 * 113) }
        let entire = DoorbellG722Encoder().encode(pcm)
        let encoder = DoorbellG722Encoder()
        var split = Data()
        for start in stride(from: 0, to: pcm.count, by: 320) { split.append(encoder.encode(Array(pcm[start..<start + 320]))) }
        XCTAssertEqual(entire, split)
        let decoder = DoorbellG722Decoder()
        var output: [Int16] = []
        for start in stride(from: 0, to: split.count, by: 160) { output += decoder.decode(split.subdata(in: start..<start + 160)) }
        XCTAssertEqual(output, DoorbellG722Decoder().decode(entire))
    }

    func testRTPClockUsesEightKilohertzAndWrapsSequence() {
        var packetizer = DoorbellRTPPacketizer(sequence: .max, timestamp: .max - 79, ssrc: 0x12345678)
        let first = packetizer.packet(Data(repeating: 0xfa, count: 160))
        XCTAssertEqual(Array(first.prefix(12)), [0x80, 0x89, 0xff, 0xff, 0xff, 0xff, 0xff, 0xb0, 0x12, 0x34, 0x56, 0x78])
        XCTAssertEqual(packetizer.sequence, 0)
        XCTAssertEqual(packetizer.timestamp, 80)
        let next = packetizer.packet(Data(repeating: 0xfa, count: 160), type: 97)
        XCTAssertEqual(next[1], 97)
        XCTAssertEqual(next[7], 80)
        XCTAssertEqual(DoorbellRTPPacketizer.payload(next, type: 97), Data(repeating: 0xfa, count: 160))
    }

    func testRTPPayloadSkipsCSRCHeaderExtensionAndPadding() {
        var packet = Data([0xb1, 9, 0, 1, 0, 0, 0, 1, 0, 0, 0, 1])
        packet.append(contentsOf: [0, 0, 0, 2]) // CSRC
        packet.append(contentsOf: [0xab, 0xcd, 0, 1, 1, 2, 3, 4]) // one extension word
        packet.append(contentsOf: [0xfa, 0xfb, 0, 2]) // two octets payload and padding
        XCTAssertEqual(DoorbellRTPPacketizer.payload(packet, type: 9), Data([0xfa, 0xfb]))
        XCTAssertNil(DoorbellRTPPacketizer.payload(packet, type: 8))
        XCTAssertNil(DoorbellRTPPacketizer.payload(Data(packet.prefix(17)), type: 9))
        packet[packet.count - 1] = 100
        XCTAssertNil(DoorbellRTPPacketizer.payload(packet, type: 9))
    }

    func testSDPSeparatesListeningAndBackchannelAndHonorsDynamicPayload() throws {
        let sdp = """
        v=0
        m=audio 0 RTP/AVP 9
        a=rtpmap:9 G722/8000
        a=recvonly
        a=control:trackID=1
        m=audio 0 RTP/AVP 97
        a=rtpmap:97 G722/8000
        a=sendonly
        a=control:trackID=2
        """
        XCTAssertEqual(try DoorbellAudioTrack.parse(sdp, base: "rtsp://camera:554/live", backchannel: false), .init(uri: "rtsp://camera:554/live/trackID=1", payloadType: 9))
        XCTAssertEqual(try DoorbellAudioTrack.parse(sdp, base: "rtsp://camera:554/live", backchannel: true), .init(uri: "rtsp://camera:554/live/trackID=2", payloadType: 97))
    }

    func testSDPRejectsUnsupportedCodecAndDifferentControlHost() {
        XCTAssertThrowsError(try DoorbellAudioTrack.parse("m=audio 0 RTP/AVP 0\na=sendonly\na=control:track", base: "rtsp://camera/live", backchannel: true))
        XCTAssertThrowsError(try DoorbellAudioTrack.parse("m=audio 0 RTP/AVP 9\na=sendonly\na=control:rtsp://different/live", base: "rtsp://camera/live", backchannel: true))
    }

    func testSDPResolvesRootRelativeAudioControl() throws {
        let parsed = try DoorbellAudioTrack.parse("m=audio 0 RTP/AVP 9\na=sendonly\na=control:/backchannel", base: "rtsp://camera:8554/live/", backchannel: true)
        XCTAssertEqual(parsed.uri, "rtsp://camera:8554/backchannel")
    }

    @MainActor
    func testAudioBeginsOffAndStopIsIdempotentWithoutRequestingMicrophone() {
        let audio = DoorbellAudio()
        XCTAssertFalse(audio.microphoneEnabled)
        XCTAssertFalse(audio.listeningEnabled)
        XCTAssertFalse(audio.connecting)
        audio.stop(); audio.stop()
        XCTAssertEqual(audio.status, "Audio off")
    }

    @MainActor
    func testCancelledQueuedAudioCannotRequestMicrophoneOrOpenSpeaker() async {
        let audio = DoorbellAudio()
        let camera = CameraDescriptor(id: "doorbell", name: "Doorbell", host: "recorder.invalid", sourceToken: "source",
            mainProfile: "main", subProfile: "sub", mainURI: "rtsp://recorder.invalid/main", subURI: "rtsp://recorder.invalid/sub",
            mainRecording: nil, subRecording: nil, mainWidth: 640, mainHeight: 360, subWidth: 640, subHeight: 360,
            rotationDegrees: 0, isDoorbell: true, isCorridor: false)
        let configuration = RecorderConfiguration(host: "recorder.invalid", username: "test", password: "")
        let work = Task { @MainActor in
            await audio.startTalking(camera: camera, configuration: configuration)
            await audio.setListening(true, camera: camera, configuration: configuration)
        }
        work.cancel()
        await work.value
        XCTAssertFalse(audio.microphoneEnabled)
        XCTAssertFalse(audio.listeningEnabled)
        XCTAssertFalse(audio.connecting)
        XCTAssertEqual(audio.status, "Audio off")
    }

    private func digest(_ data: Data) -> String { SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined() }
}
